<script setup lang="ts">
import {
  ClearOutlined,
  DeleteOutlined,
  EditOutlined,
  PlusOutlined,
  ReloadOutlined,
  SearchOutlined,
} from '@ant-design/icons-vue';
import { useAccess } from '@vben/access';
import { message, Modal, type FormInstance } from 'ant-design-vue';
import { computed, onMounted, reactive, ref } from 'vue';

import {
  createPlatformUser,
  deletePlatformUser,
  getPlatformUserList,
  updatePlatformUser,
  type PlatformUser,
  type PlatformUserPayload,
} from '#/api/kadmin/generated/platform_user';

type TablePagination = { current?: number; pageSize?: number };

const { hasAccessByCodes } = useAccess();
const canCreate = computed(() => hasAccessByCodes(['system:platform_user:create', '*']));
const canUpdate = computed(() => hasAccessByCodes(['system:platform_user:update', '*']));
const canDelete = computed(() => hasAccessByCodes(['system:platform_user:delete', '*']));

const loading = ref(false);
const errorText = ref('');
const items = ref<PlatformUser[]>([]);
const total = ref(0);
const page = ref(1);
const pageSize = ref(20);

const filters = reactive<Record<string, string>>({
  userName: '',
  password: '',
  avatar: '',
  status: '',
  creatBy: '',
  createTime: '',
  updateBy: '',
  updateTime: '',
  remark: '',
});

const columns = [
  { title: 'User Id', dataIndex: 'userId', key: 'userId', width: 160, ellipsis: true },
  { title: 'User Name', dataIndex: 'userName', key: 'userName', width: 160, ellipsis: true },
  { title: 'Password', dataIndex: 'password', key: 'password', width: 160, ellipsis: true },
  { title: 'Avatar', dataIndex: 'avatar', key: 'avatar', width: 160, ellipsis: true },
  { title: '上传文件数量（冗余计数，Go 侧事务维护）', dataIndex: 'count', key: 'count', width: 160, ellipsis: true },
  { title: '账号状态（0为封禁，1为正常，与RuoYi相反）', dataIndex: 'status', key: 'status', width: 160, ellipsis: true },
  { title: '创建者（源库拼写如此，原样保留）', dataIndex: 'creatBy', key: 'creatBy', width: 160, ellipsis: true },
  { title: 'Create Time', dataIndex: 'createTime', key: 'createTime', width: 160, ellipsis: true },
  { title: 'Update By', dataIndex: 'updateBy', key: 'updateBy', width: 160, ellipsis: true },
  { title: 'Update Time', dataIndex: 'updateTime', key: 'updateTime', width: 160, ellipsis: true },
  { title: 'Remark', dataIndex: 'remark', key: 'remark', width: 160, ellipsis: true },
  { title: '操作', key: 'action', width: 120, fixed: 'right' },
];

const pagination = computed(() => ({
  current: page.value,
  pageSize: pageSize.value,
  pageSizeOptions: ['10', '20', '50', '100'],
  showSizeChanger: true,
  showTotal: (value: number) => `共 ${value} 条`,
  total: total.value,
}));

async function fetchList() {
  loading.value = true;
  errorText.value = '';
  try {
    const result = await getPlatformUserList({
      page: page.value,
      pageSize: pageSize.value,
      userName: filters.userName || undefined,
      password: filters.password || undefined,
      avatar: filters.avatar || undefined,
      status: filters.status || undefined,
      creatBy: filters.creatBy || undefined,
      createTime: filters.createTime || undefined,
      updateBy: filters.updateBy || undefined,
      updateTime: filters.updateTime || undefined,
      remark: filters.remark || undefined,
    });
    items.value = result.items;
    total.value = result.total;
  } catch (error) {
    errorText.value = error instanceof Error ? error.message : '加载失败';
  } finally {
    loading.value = false;
  }
}

function search() {
  page.value = 1;
  void fetchList();
}

function resetSearch() {
  filters.userName = '';
  filters.password = '';
  filters.avatar = '';
  filters.status = '';
  filters.creatBy = '';
  filters.createTime = '';
  filters.updateBy = '';
  filters.updateTime = '';
  filters.remark = '';
  search();
}

function handleTableChange(paginationValue: TablePagination) {
  page.value = paginationValue.current ?? 1;
  pageSize.value = paginationValue.pageSize ?? 20;
  void fetchList();
}

const modalOpen = ref(false);
const submitting = ref(false);
const editingId = ref<null | number>(null);
const formRef = ref<FormInstance>();
const dirty = ref(false);

const formState = reactive<Record<string, any>>({
  userName: '',
  password: '',
  avatar: '',
  count: undefined,
  status: '',
  creatBy: '',
  createTime: '',
  updateBy: '',
  updateTime: '',
  remark: '',
});

const rules: Record<string, unknown> = {
  userName: [{ required: true, message: '请输入User Name', trigger: 'blur' }],
};

function openCreate() {
  editingId.value = null;
  dirty.value = false;
  formState.userName = '';
  formState.password = '';
  formState.avatar = '';
  formState.count = undefined;
  formState.status = '';
  formState.creatBy = '';
  formState.createTime = '';
  formState.updateBy = '';
  formState.updateTime = '';
  formState.remark = '';
  modalOpen.value = true;
}

async function openEdit(record: PlatformUser) {
  editingId.value = record.userId;
  dirty.value = false;
  formState.userName = record.userName;
  formState.password = record.password;
  formState.avatar = record.avatar;
  formState.count = record.count;
  formState.status = record.status;
  formState.creatBy = record.creatBy;
  formState.createTime = record.createTime;
  formState.updateBy = record.updateBy;
  formState.updateTime = record.updateTime;
  formState.remark = record.remark;
  modalOpen.value = true;
}

function requestClose() {
  if (!dirty.value) {
    modalOpen.value = false;
    return;
  }
  Modal.confirm({
    title: '放弃修改？',
    content: '当前表单有未保存的修改。',
    okText: '放弃',
    okType: 'danger',
    cancelText: '继续编辑',
    onOk: () => {
      dirty.value = false;
      modalOpen.value = false;
    },
  });
}

function markDirty() {
  if (modalOpen.value) {
    dirty.value = true;
  }
}

async function submit() {
  try {
    await formRef.value?.validate();
  } catch {
    return;
  }
  submitting.value = true;
  try {
    const payload = {
      userName: formState.userName,
      password: formState.password,
      avatar: formState.avatar,
      count: formState.count,
      status: formState.status,
      creatBy: formState.creatBy,
      createTime: formState.createTime,
      updateBy: formState.updateBy,
      updateTime: formState.updateTime,
      remark: formState.remark,
    } as PlatformUserPayload;
    if (editingId.value === null) {
      await createPlatformUser(payload);
      message.success('新增成功');
    } else {
      await updatePlatformUser(editingId.value, payload);
      message.success('修改成功');
    }
    modalOpen.value = false;
    dirty.value = false;
    await fetchList();
  } catch (error) {
    message.error(error instanceof Error ? error.message : '提交失败');
  } finally {
    submitting.value = false;
  }
}

async function remove(record: PlatformUser) {
  try {
    await deletePlatformUser(record.userId);
    message.success('删除成功');
    await fetchList();
  } catch (error) {
    message.error(error instanceof Error ? error.message : '删除失败');
  }
}

onMounted(() => {
  void fetchList();
});
</script>
